/*
 * Handlebars AST interpreter that never evals.
 *
 * Rendering happens in two phases. `build` walks the AST once into a tree of
 * closures, one per node, cached per Program, so a template pays for the walk
 * once however often it renders. Rendering is then just calling the root
 * closure with a frame. render.ts owns both.
 *
 * Async is carried by `Pending`, in pending.ts. A render that invokes nothing
 * async allocates no promise.
 */
// consumers compile this out of node_modules, where their tsconfig `include`
// does not reach and only a triple-slash reference pulls in the augmentation.
// eslint-disable-next-line @typescript-eslint/triple-slash-reference
/// <reference path="./types/handlebars-parser.d.ts" />
import { Exception } from '@handlebars/parser'
import type { AST as Hbs } from '@handlebars/parser'
import { cachedParse } from './cache.ts'
import { renderAst } from './render.ts'
import type { RuntimeOptions } from './frame.ts'

export default function briskbars (
  template: string | Hbs.Program,
  context: unknown,
  runtimeOptions: RuntimeOptions = {}
): string | Promise<string> {
  if (
    template == null ||
    (typeof template !== 'string' && template.type !== 'Program')
  ) {
    throw new Exception(
      'You must pass a string or Handlebars AST. You passed ' +
        template
    )
  }
  return renderAst(
    typeof template === 'string' ? cachedParse(template).ast : template,
    context,
    runtimeOptions
  )
}

export { parse } from '@handlebars/parser'
export { default as SafeString } from '../lib/handlebars/safe-string.js'
export { createFrame } from '../lib/handlebars/utils.js'
export { escapeExpression } from './vendor.ts'
export { loopEntry, loopEntryKey } from './helpers.ts'
export type { LoopEntry } from './helpers.ts'
export type { HelperLocation, HelperOptions, RuntimeOptions } from './frame.ts'
