/*
 * Reading a value out of a frame: prototype-access control, `../` depths,
 * @data, and block params.
 *
 * `planPath` does the regex and scope work once per node at build time and
 * hands `resolvePlan` a flat plan to walk per render.
 */
import { Visitor } from '@handlebars/parser'
import type { AST as Hbs } from '@handlebars/parser'
import AST from '../lib/handlebars/compiler/ast.js'
import {
  createProtoAccessControl,
  resultIsAllowed,
} from '../lib/handlebars/internal/proto-access.js'
import { isMap } from './vendor.ts'
import type { BlockParamScopes, DataFrame, Frame } from './frame.ts'

// upstream's defaults, built once and never reconfigurable. Passing `{}` leaves
// both defaultValues undefined, which keeps the one-time warning on a denied
// member. An explicit false would deny silently.
const defaultProtoAccess = createProtoAccessControl({})

export function defaultLookupProperty (parent: unknown, name: string): unknown {
  if (parent == null) {
    return undefined
  }
  // isMap calls Object.prototype.toString, too costly on every lookup. `get` is
  // the precondition, and a non-Map with one falls through to the real check.
  if (typeof (parent as { get?: unknown }).get === 'function' && isMap(parent)) {
    return parent.get(name)
  }
  const result = (parent as Record<string, unknown>)[name]
  if (result == null) {
    return result
  }
  if (Object.prototype.hasOwnProperty.call(parent, name)) {
    return result
  }
  if (resultIsAllowed(result, defaultProtoAccess, name)) {
    return result
  }
  return undefined
}

// everything about a path that doesn't depend on the frame, so the regexes and
// the block param search run once per node
export interface PathPlan {
  node: Hbs.PathExpression;
  data: boolean;
  parts: string[];
  depth: number;
  original: string;
  // one part, unscoped, depth 0, not @data, so it may name a helper
  simple: boolean;
  // block params are lexically scoped, so the slot is known at build time
  blockParam: { depth: number; idx: number } | null;
}

function findBlockParamSlot (
  scopes: BlockParamScopes,
  name: string
): { depth: number; idx: number } | null {
  for (let depth = 0; depth < scopes.length; depth++) {
    const idx = scopes[depth].indexOf(name)
    if (idx >= 0) {
      return { depth, idx }
    }
  }
  return null
}

// the grammar allows a literal where the AST types promise a PathExpression
// (`{{#true}}`), so rewrite it and let build see only the two real cases
export function normalizePath (
  path: Hbs.PathExpression | Hbs.SubExpression | Hbs.Literal
): Hbs.PathExpression | Hbs.SubExpression {
  // a SubExpression has no `parts` either, so exclude by type, not by shape
  if (path && path.type !== 'PathExpression' && path.type !== 'SubExpression') {
    const literal = path as Hbs.Literal & { original?: unknown }
    return {
      type: 'PathExpression',
      data: false,
      depth: 0,
      parts: [String(literal.original)],
      original: String(literal.original),
      loc: literal.loc,
    } as Hbs.PathExpression
  }
  // Literal declares `.type` as the loose base string, so the checks above
  // narrow nothing and the cast has to state what they proved
  return path as Hbs.PathExpression | Hbs.SubExpression
}

export function planPath (path: Hbs.PathExpression, scopes: BlockParamScopes): PathPlan {
  const parts = (path.parts || []) as string[]
  const name = parts[0]
  const scoped = AST.helpers.scopedId(path)
  // reruns scopedId's regex, but at build time, and defers the rule to upstream
  const simple = !path.data && AST.helpers.simpleId(path)

  const eligible =
    !path.data && !path.depth && !!name && name !== 'this' && name !== '.' && !scoped

  return {
    node: path,
    data: !!path.data,
    parts,
    depth: path.depth || 0,
    original: path.original,
    simple,
    blockParam: eligible ? findBlockParamSlot(scopes, name) : null,
  }
}

// every part goes through lookupProperty, so a `{{a.b.c}}` cannot slip past
// prototype-access control partway down. A null anywhere ends the walk.
function walkParts (
  frame: Frame,
  root: unknown,
  parts: string[],
  from: number
): unknown {
  let result = root
  for (let i = from; i < parts.length; i++) {
    if (result == null) {
      return undefined
    }
    result = frame.lookupProperty(result, parts[i])
  }
  return result
}

export function resolvePlan (plan: PathPlan, frame: Frame): unknown {
  const parts = plan.parts

  if (plan.data) {
    return lookupData(frame, parts, plan.depth)
  }

  // the slot holds the value itself, so any remaining parts walk off it
  if (plan.blockParam) {
    const bound = frame.blockParamValues[plan.blockParam.depth][plan.blockParam.idx]
    return walkParts(frame, bound, parts, 1)
  }

  const ctx = plan.depth ? frame.depths[plan.depth] ?? null : frame.context

  // `{{.}}` and `{{..}}` name the context itself
  if (!parts.length || parts[0] === '.') {
    return ctx
  }

  return walkParts(frame, ctx, parts, 0)
}

function lookupData (frame: Frame, parts: string[], depth: number): unknown {
  let d: unknown = frame.data
  for (let i = 0; i < depth; i++) {
    d = d && (d as DataFrame)._parent
  }
  if (!parts.length) {
    return d
  }
  // through lookupProperty, since @root leads back into user context where
  // prototype-access control still applies
  return walkParts(frame, d, parts, 0)
}

class DepthScan extends Visitor {
  found = false

  PathExpression (path: Hbs.PathExpression): void {
    if (path.depth) {
      this.found = true
    }
  }
}

// whether a `../` path appears anywhere below, nested blocks included.
// Upstream's compiler tracks the same thing as `useDepths`.
export function usesDepths (program: Hbs.Program): boolean {
  const scan = new DepthScan()
  scan.accept(program)
  return scan.found
}
