/*
 * The two-phase core.
 *
 * `build*` walks the AST once into a tree of closures, one per node, cached per
 * Program on a WeakMap. `run*` is what those closures do per render. The walk
 * is mutually recursive across programs, statements, blocks and partials, so it
 * lives in one module rather than a ring of importing ones.
 */
import { Exception } from '@handlebars/parser'
import type { AST as Hbs } from '@handlebars/parser'
import AST from '../lib/handlebars/compiler/ast.js'
import { createFrame } from '../lib/handlebars/utils.js'
import { escapeExpression, extend, invokePartial } from './vendor.ts'
import { Pending, chain, continueAll, invoked, settle } from './pending.ts'
import type { Rendered } from './pending.ts'
import { asCallable, derive, emptyHelpers, emptyPartials, emptyScopes, emptyValues, noopProgram, stringify } from './frame.ts'
import type { BlockParamScopes, DataFrame, Frame, NodeFn, Partial, PartialCallOptions, PartialFn, PartialsMap, ProgramFn, ProgramFnOptions, RuntimeOptions, ValueFn } from './frame.ts'
import type { StatementNode } from './ast.ts'
import { cachedParse } from './cache.ts'
import {
  defaultLookupProperty,
  normalizePath,
  planPath,
  resolvePlan,
  usesDepths,
} from './lookup.ts'
import { findHelper, missingHelper } from './helpers.ts'
import {
  buildExpression,
  helperOptions,
  buildValue,
  planCall,
  runCall,
  runHash,
} from './calls.ts'
import type { CallPlan } from './calls.ts'

// ---------------------------------------------------------------------------
// Program bodies
// ---------------------------------------------------------------------------

// once a node suspends, the nodes after it start without waiting for it
function renderAll (nodes: NodeFn[], frame: Frame): Rendered {
  let out = ''
  for (let i = 0; i < nodes.length; i++) {
    const value = nodes[i](frame)
    if (value instanceof Pending) {
      return continueAll([out, value], i + 1, nodes.length, (j) => nodes[j](frame),
        (parts) => parts.join(''))
    }
    out += (value as string) || ''
  }
  return out
}

interface InlineDefinition {
  name: string;
  body: NodeFn;
}

// a Program sits at exactly one position in the AST, so its enclosing block
// param scopes are fixed and the built tree can be cached on the node
const builtPrograms = new WeakMap<Hbs.Program, NodeFn>()

function buildRender (
  body: StatementNode[],
  scopes: BlockParamScopes,
  inlines: InlineDefinition[]
): NodeFn {
  const children: NodeFn[] = []
  // content separated only by a node that renders nothing, a comment or an
  // {{#*inline}} block, still renders back to back, so the run folds to one
  // closure
  let text = ''
  let onlyText = true
  const flushText = (): void => {
    if (text) {
      const value = text
      children.push(() => value)
      text = ''
    }
  }

  for (const node of body) {
    if (node.type === 'ContentStatement') {
      text += node.value
      continue
    }
    const child = buildStatement(node, scopes)
    if (!child) {
      continue
    }
    flushText()
    children.push(child)
    onlyText = false
  }
  flushText()

  // nothing but text, so the body never varies and needs no loop
  if (onlyText) {
    return children[0] || (() => '')
  }

  const renderBody: NodeFn = (frame) => renderAll(children, frame)
  return inlines.length
    ? (frame) => renderBody(withInlinePartials(frame, inlines))
    : renderBody
}

function buildProgram (program: Hbs.Program, outerScopes: BlockParamScopes): NodeFn {
  const cached = builtPrograms.get(program)
  if (cached) {
    return cached
  }

  // `as |a b|` introduces a scope for the body, matching what its ProgramFn
  // pushes onto frame.blockParamValues
  const scopes: BlockParamScopes =
    program.blockParams && program.blockParams.length
      ? [program.blockParams, ...outerScopes]
      : outerScopes

  const inlines = buildInlineDefinitions(program, scopes)
  const render = buildRender((program.body || []) as StatementNode[], scopes, inlines)
  builtPrograms.set(program, render)
  return render
}

// visible inside the program that defines them, and from a {{#> partial}} block
// to the called partial, so planPartial builds them too
function buildInlineDefinitions (
  program: Hbs.Program,
  scopes: BlockParamScopes
): InlineDefinition[] {
  if (!program.body) {
    return []
  }
  const definitions: InlineDefinition[] = []
  for (const node of program.body as Hbs.Node[]) {
    if (
      node.type !== 'DecoratorBlock' ||
      (node as Hbs.DecoratorBlock).path.original !== 'inline'
    ) {
      continue
    }
    const decorator = node as Hbs.DecoratorBlock
    const nameNode = decorator.params[0]
    // upstream evaluates decorator args at runtime. Only literals here.
    if (!nameNode || nameNode.type !== 'StringLiteral') {
      throw new Exception('Inline partial names must be string literals', decorator)
    }
    definitions.push({
      name: (nameNode as Hbs.StringLiteral).value,
      body: buildProgram(decorator.program, scopes),
    })
  }
  return definitions
}

// the closures are made per invocation, since each captures the live frame
function withInlinePartials (frame: Frame, inlines: InlineDefinition[]): Frame {
  const partials: Record<string, Partial> = { ...frame.partials }
  for (const inline of inlines) {
    partials[inline.name] = ((ctx: unknown, opts: PartialCallOptions = {}) => {
      const inner = derive(
        frame, ctx, opts.data || frame.data, frame.depths,
        opts.partials || partials,
        frame.blockParamValues
      )
      // the caller's options, so the depth keeps counting
      inner.options = opts
      return settle(inline.body(inner))
    }) as PartialFn
  }
  return derive(
    frame, frame.context, frame.data, frame.depths, partials, frame.blockParamValues
  )
}

// three levels, because a helper calls `options.fn(context)` with no frame of
// its own: this builds the body once, returns a maker that binds one frame, and
// that maker returns the `fn` the helper actually calls.
function buildProgramFn (
  program: Hbs.Program,
  scopes: BlockParamScopes
): (frame: Frame) => ProgramFn {
  const render = buildProgram(program, scopes)
  const declared = program.blockParams ? program.blockParams.length : 0
  // depths exists only to answer `../`, so when nothing below asks, the copy is
  // one wasted array per loop iteration
  const pushesDepth = usesDepths(program)

  return (frame) => {
    // fnOptions stays optional but loses its `= {}` default, which allocated an
    // object per call just to read two absent keys off. A helper that does pass
    // one, to switch the data frame or bind block params, is read below.
    const fn = ((context?: unknown, fnOptions?: ProgramFnOptions): string | Promise<string> => {
      const blockParamValues = declared
        ? [fnOptions?.blockParams || emptyValues, ...frame.blockParamValues]
        : frame.blockParamValues

      const data = fnOptions?.data || frame.data

      // loose, matching wrapProgram upstream. It matters: iterating a one
      // element array binds the item, and `1 != [1]` is false, so upstream
      // pushes no level there and every `../` below counts one less.
      const depths = pushesDepth && context != frame.depths[0]
        ? [context, ...frame.depths]
        : frame.depths

      return settle(render(derive(
        frame, context, data, depths, frame.partials, blockParamValues
      )))
    }) as ProgramFn

    // eachOver only tests it for truth, so 0 and absent are the same answer
    if (declared) {
      fn.blockParams = declared
    }
    return fn
  }
}

// ---------------------------------------------------------------------------
// Statements
// ---------------------------------------------------------------------------

// no ContentStatement case: buildRender, the only caller, accumulates content
// itself, so a run of it separated by comments folds to one closure.
function buildStatement (node: StatementNode, scopes: BlockParamScopes): NodeFn | null {
  switch (node.type) {
    case 'MustacheStatement':
      return buildMustache(node, scopes)
    case 'BlockStatement':
      return buildBlock(node, scopes)
    case 'PartialStatement':
    case 'PartialBlockStatement': {
      const plan = planPartial(node, scopes)
      return (frame) => runPartial(plan, frame)
    }
    case 'DecoratorBlock':
    case 'Decorator':
    case 'CommentStatement':
      return null
    default:
      // thrown when reached, so an unknown node in a dead branch stays harmless
      return () => {
        throw new Exception(
          'Unknown node type: ' + (node as Hbs.Node).type,
          node as Hbs.Node
        )
      }
  }
}

function buildMustache (node: Hbs.MustacheStatement, scopes: BlockParamScopes): NodeFn {
  const value = buildExpression(node, scopes)
  const render = node.escaped ? escapeExpression : stringify
  return (frame) => chain(value(frame), render)
}

// everything about a block reference that is fixed at build time
interface BlockPlan {
  call: CallPlan;
  name: string;
  // a simple id that is not a block param, so it may name a helper and its
  // lambda receives the options object
  ambiguous: boolean;
}

// no params, so the value is a lambda or plain data and blockHelperMissing
// decides what the block means. Only an ambiguous simple id ({{#foo}}) gets the
// options object. Every other lambda is called with nothing.
function runImplicitBlock (
  block: BlockPlan,
  frame: Frame,
  resolved: unknown,
  fn: ProgramFn,
  inverse: ProgramFn
): unknown {
  return chain(runHash(block.call, frame), (hash) => {
    const options = helperOptions(
      block.name, hash, frame, fn, inverse, block.call.loc
    )
    const lambda = asCallable(resolved)
    const lambdaResult = lambda
      ? invoked(block.ambiguous
        ? lambda.call(frame.context, options)
        : lambda.call(frame.context))
      : resolved

    return chain(lambdaResult, (result) => invoked(
      missingHelper(frame, 'blockHelperMissing').call(frame.context, result, options)
    ))
  })
}

function buildBlock (node: Hbs.BlockStatement, scopes: BlockParamScopes): NodeFn {
  // the grammar allows a literal block path (`{{#true}}`), even though the
  // upstream type says BlockStatement.path is always a PathExpression
  const rawPath = normalizePath(
    node.path as unknown as Hbs.PathExpression | Hbs.SubExpression | Hbs.Literal
  ) as Hbs.PathExpression

  const plan = planPath(rawPath, scopes)
  const isBlockParam = plan.simple && plan.blockParam !== null
  const hasParams = !isBlockParam && AST.helpers.helperExpression(node)
  const block: BlockPlan = {
    call: planCall(node.params, node.hash, scopes, node.loc),
    // the grammar rejects a subexpression here and normalizePath rewrote any
    // literal, so the path is always a PathExpression and always has a name
    name: plan.original,
    ambiguous: plan.simple && !isBlockParam,
  }

  const makeFn = node.program ? buildProgramFn(node.program, scopes) : null
  const makeInverse = node.inverse ? buildProgramFn(node.inverse, scopes) : null

  // one closure rather than a ValueFn wrapped in a stringifying NodeFn, which
  // cost a call per invocation
  return (frame) => {
    const fn = makeFn ? makeFn(frame) : noopProgram
    const inverse = makeInverse ? makeInverse(frame) : noopProgram

    // the registry is only consulted for simple ids: pathed, depthed and scoped
    // names always resolve from the context
    const helper = block.ambiguous ? findHelper(frame, block.name) : undefined

    let result: unknown
    if (helper) {
      result = runCall(block.call, helper, block.name, frame, fn, inverse)
    } else {
      // resolved before the hash, matching the order params are evaluated in
      const resolved = resolvePlan(plan, frame)
      result = hasParams
        ? runCall(
          block.call,
          asCallable(resolved) || missingHelper(frame, 'helperMissing'),
          block.name,
          frame,
          fn,
          inverse
        )
        : runImplicitBlock(block, frame, resolved, fn, inverse)
    }

    return chain(result, stringify)
  }
}

// only the AST is captured, so the cached fn holds no state from the render
// that compiled it
function compileStringPartial (source: string): PartialFn {
  const entry = cachedParse(source)
  if (!entry.fn) {
    const ast = entry.ast
    // callPartial always passes options
    entry.fn = (context, options) => renderAst(ast, context, options!)
  }
  return entry.fn
}

// ---------------------------------------------------------------------------
// Partials
// ---------------------------------------------------------------------------

interface PartialPlan {
  node: Hbs.PartialStatement | Hbs.PartialBlockStatement;
  // present when the name is a subexpression, so it resolves per render
  nameFn: ValueFn | null;
  // empty when nameFn is set, which is the only case that leaves it unread
  staticName: string;
  contextFn: ValueFn | null;
  hash: CallPlan | null;
  indent: string;
  // a {{#> partial}} block's body, and the inline partials it defines
  makeFn: ((frame: Frame) => ProgramFn) | null;
  inlines: InlineDefinition[];
}

function planPartial (
  node: Hbs.PartialStatement | Hbs.PartialBlockStatement,
  scopes: BlockParamScopes
): PartialPlan {
  const nameNode = node.name as
    Hbs.PathExpression | Hbs.SubExpression | Hbs.Literal
  const params = node.params || []
  // upstream's compiler rejects this too, before anything renders
  if (params.length > 1) {
    throw new Exception('Unsupported number of partial arguments: ' + params.length, node)
  }
  // a subexpression name is the one shape with no `original`. PathExpression
  // (`{{> foo}}`, `{{> [a b]}}`), StringLiteral (`{{> "a b"}}`) and
  // NumberLiteral (`{{> 42}}`) all carry one, so String() covers the numeric
  // case rather than leaving a number typed as a string.
  const dynamic = nameNode.type === 'SubExpression'
  const program = (node as Hbs.PartialBlockStatement).program
  return {
    node,
    nameFn: dynamic ? buildExpression(nameNode as Hbs.SubExpression, scopes) : null,
    staticName: dynamic
      ? ''
      : String((nameNode as { original: unknown }).original),
    contextFn: params.length > 0 ? buildValue(params[0], scopes) : null,
    hash: node.hash ? planCall(undefined, node.hash, scopes) : null,
    indent: (node as Hbs.PartialStatement).indent || '',
    makeFn: program ? buildProgramFn(program, scopes) : null,
    inlines: program ? buildInlineDefinitions(program, scopes) : [],
  }
}

// the name can come from the template or, for `{{> (dynamic)}}`, from data, so
// it gets the same guard findHelper puts on the helper registry. Without it
// `{{> toString}}` reaches Object.prototype and calls what it finds there.
function findPartial (partials: PartialsMap, name: string): Partial | undefined {
  return Object.prototype.hasOwnProperty.call(partials, name)
    ? partials[name]
    : undefined
}

// looks the partial up and, if it is source text, compiles it. env.compile is
// never consulted: in real Handlebars it runs the eval-based compiler this
// interpreter avoids.
function resolvePartialFn (frame: Frame, partialName: string): PartialFn | undefined {
  const partial: Partial | undefined = partialName === '@partial-block'
    ? frame.data && (frame.data['partial-block'] as Partial | undefined)
    : findPartial(frame.partials, partialName)

  if (typeof partial === 'string') {
    try {
      return compileStringPartial(partial)
    } catch (err) {
      const detail = err instanceof Error ? err.message : String(err)
      const exception = new Exception(
        'The partial ' + partialName + ' could not be compiled: ' + detail
      )
      exception.cause = err
      throw exception
    }
  }
  return partial || undefined
}

// async recursion never overflows the stack, so it needs its own limit
const partialDepthLimit = 1000

// a hash merges into the context the partial renders against, and `indent`
// re-indents what it produced
function callPartial (plan: PartialPlan, frame: Frame, name: string): Rendered {
  // internal, so not declared on RuntimeOptions
  const partialDepth = ((frame.options as PartialCallOptions).partialDepth as number || 0) + 1
  if (partialDepth > partialDepthLimit) {
    throw new Exception(
      'Partials nested more than ' + partialDepthLimit +
        ' deep. Does a partial include itself?',
      plan.node
    )
  }
  const partial = resolvePartialFn(frame, name)
  const fn = plan.makeFn ? plan.makeFn(frame) : undefined
  if (!partial && !fn) {
    throw new Exception('The partial "' + name + '" could not be found')
  }
  return chain(
    plan.contextFn ? plan.contextFn(frame) : frame.context,
    (context) => chain(plan.hash ? runHash(plan.hash, frame) : null, (hash) => {
      const target = hash
        ? extend({}, context, hash)
        : context

      const callOpts: PartialCallOptions = {
        ...frame.options,
        helpers: frame.helpers,
        partials: plan.inlines.length
          ? withInlinePartials(frame, plan.inlines).partials
          : frame.partials,
        data: frame.data,
        partialDepth,
      }

      // invokePartial is only needed to make a block @partial-block. A missing
      // partial renders its block directly, and a blockless one is just called.
      let result
      if (!partial) {
        result = fn!(target, { data: frame.data })
      } else if (fn) {
        callOpts.fn = fn
        result = invokePartial(partial, target, callOpts)
      } else {
        result = partial(target, callOpts)
      }
      return chain(invoked(result), (rendered) =>
        indentResult((rendered as string) || '', plan.indent))
    })
  )
}

function runPartial (plan: PartialPlan, frame: Frame): Rendered {
  if (!plan.nameFn) {
    return callPartial(plan, frame, plan.staticName)
  }
  return chain(plan.nameFn(frame), (name) => callPartial(plan, frame, name as string))
}

function indentResult (result: string, indent: string): string {
  if (!indent || !result) {
    return result
  }
  // every line except the empty one a trailing newline leaves behind. No `m`
  // flag, so `$` only matches a newline ending the string.
  return indent + result.replace(/\n(?!$)/g, '\n' + indent)
}

// a frame propagated from a parent render already carries @root and is used
// as-is. Anything else is a plain object the caller passed, and gets wrapped.
function initData (context: unknown, data: DataFrame | undefined): DataFrame {
  if (data && typeof data === 'object' && 'root' in data) {
    return data
  }
  const frame: DataFrame = data && typeof data === 'object' ? createFrame(data) : {}
  frame.root = context
  return frame
}

// the render half of the entry point, reached from briskbars() and from a
// string partial the source cache just parsed. Takes an AST, so neither caller
// has to know how the template was spelled.
export function renderAst (
  ast: Hbs.Program,
  context: unknown,
  runtimeOptions: RuntimeOptions
): string | Promise<string> {
  // cached on the Program node, so the walk happens once per template
  const render = buildProgram(ast, emptyScopes)

  const data = initData(context, runtimeOptions.data)

  // neither map is copied, and neither is written to
  const helpers = runtimeOptions.helpers || emptyHelpers
  const partials = runtimeOptions.partials || emptyPartials

  return settle(render({
    context,
    data,
    depths: [context],
    helpers,
    partials,
    blockParamValues: [],
    lookupProperty: defaultLookupProperty,
    options: runtimeOptions,
  }))
}
