/*
 * Calling something: a helper, a lambda found in the context, or
 * helperMissing. `planCall` compiles params and hash values to closures once,
 * and `runCall` walks them per render, suspending if any of them do.
 */
import { Exception } from '@handlebars/parser'
import type { AST as Hbs } from '@handlebars/parser'
import AST from '../lib/handlebars/compiler/ast.js'
import { Pending, chain, continueAll, invoked, runAll } from './pending.ts'
import { asCallable } from './frame.ts'
import type { BlockParamScopes, Frame, Helper, HelperLocation, HelperOptions, ProgramFn, ValueFn } from './frame.ts'
import type { ExpressionHolder } from './ast.ts'
import { normalizePath, planPath, resolvePlan } from './lookup.ts'
import type { PathPlan } from './lookup.ts'
import { findHelper, missingHelper } from './helpers.ts'

// params and hash values compiled to closures, hash keys hoisted out. `loc` is
// the statement or subexpression being called, which upstream passes to every
// helper as options.loc.
export interface CallPlan {
  params: ValueFn[];
  hashKeys: string[];
  hashValues: ValueFn[];
  loc: HelperLocation | undefined;
}

// options.loc built once per call site and frozen, so no helper can change it
// for the next call. Upstream builds a fresh copy per call, which cost three
// objects on every helper call.
function planLoc (loc: Hbs.SourceLocation | undefined): HelperLocation | undefined {
  if (!loc) {
    return undefined
  }
  const start = Object.freeze({ line: loc.start.line, column: loc.start.column })
  const end = Object.freeze({ line: loc.end.line, column: loc.end.column })
  // no source key at all without one, the same as upstream
  const result: HelperLocation = loc.source !== undefined
    ? { source: loc.source, start, end }
    : { start, end }
  return Object.freeze(result)
}

export function planCall (
  params: Hbs.Expression[] | undefined,
  hash: Hbs.Hash | null | undefined,
  scopes: BlockParamScopes,
  loc?: Hbs.SourceLocation
): CallPlan {
  const pairs = hash ? hash.pairs : []
  return {
    params: (params || []).map((param) => buildValue(param, scopes)),
    hashKeys: pairs.map((pair) => pair.key),
    hashValues: pairs.map((pair) => buildValue(pair.value, scopes)),
    loc: planLoc(loc),
  }
}

export function helperOptions (
  name: string | null,
  hash: Record<string, unknown>,
  frame: Frame,
  fn: ProgramFn | undefined,
  inverse: ProgramFn | undefined,
  loc: HelperLocation | undefined
): HelperOptions {
  return {
    name,
    hash,
    data: frame.data,
    lookupProperty: frame.lookupProperty,
    fn,
    inverse,
    loc,
  }
}

// never shared, since helpers receive it and may mutate it
export function runHash (plan: CallPlan, frame: Frame): Record<string, unknown> | Pending {
  const hash: Record<string, unknown> = {}
  if (!plan.hashKeys.length) {
    return hash
  }
  const pending = runAll(
    plan.hashValues.length,
    (i) => plan.hashValues[i](frame),
    (i, value) => { hash[plan.hashKeys[i]] = value }
  )
  return pending ? new Pending(pending.promise.then(() => hash)) : hash
}

export function runCall (
  plan: CallPlan,
  helper: Helper,
  name: string | null,
  frame: Frame,
  fn?: ProgramFn,
  inverse?: ProgramFn
): unknown {
  const params = plan.params
  const count = params.length
  // the extra slot is for the options object applyCall appends
  const args: unknown[] = new Array(count + 1)

  // inlined, so a call that never suspends allocates nothing. Every helper call
  // lands here, and a separate loop function measured 3-8% slower.
  for (let i = 0; i < count; i++) {
    const value = params[i](frame)
    if (value instanceof Pending) {
      return continueAll([value], i + 1, count, (j) => params[j](frame), (settled) => {
        for (let k = 0; k < settled.length; k++) {
          args[i + k] = settled[k]
        }
        return applyCall(plan, helper, name, frame, args, count, fn, inverse)
      })
    }
    args[i] = value
  }

  return applyCall(plan, helper, name, frame, args, count, fn, inverse)
}

// only the hash is left, and a hashless call cannot suspend, so it skips
// runHash and chain
function applyCall (
  plan: CallPlan,
  helper: Helper,
  name: string | null,
  frame: Frame,
  args: unknown[],
  count: number,
  fn?: ProgramFn,
  inverse?: ProgramFn
): unknown {
  if (!plan.hashKeys.length) {
    // fresh, since a helper may mutate options.hash
    args[count] = helperOptions(name, {}, frame, fn, inverse, plan.loc)
    return invoked(helper.apply(frame.context, args))
  }
  return chain(runHash(plan, frame), (hash) => {
    args[count] = helperOptions(name, hash, frame, fn, inverse, plan.loc)
    return invoked(helper.apply(frame.context, args))
  })
}

// plain context lookup. A function found there is called with no arguments,
// unlike an ambiguous simple id, whose lambda gets an options object
function buildLookup (plan: PathPlan): ValueFn {
  return (frame) => {
    const value = resolvePlan(plan, frame)
    const lambda = asCallable(value)
    return lambda ? invoked(lambda.call(frame.context)) : value
  }
}

export function buildValue (node: Hbs.Expression, scopes: BlockParamScopes): ValueFn {
  switch (node.type) {
    case 'PathExpression':
      return buildLookup(planPath(node as Hbs.PathExpression, scopes))
    case 'SubExpression':
      return buildExpression(node as Hbs.SubExpression, scopes)
    case 'StringLiteral':
    case 'NumberLiteral':
    case 'BooleanLiteral': {
      const value = (node as Hbs.StringLiteral | Hbs.NumberLiteral | Hbs.BooleanLiteral).value
      return () => value
    }
    case 'UndefinedLiteral':
      return () => undefined
    case 'NullLiteral':
      return () => null
    default:
      // thrown when reached, so an unknown node in a dead branch stays harmless
      return () => {
        throw new Exception('Unknown value type: ' + node.type, node)
      }
  }
}

// the path is itself a subexpression, so resolve it and call whatever comes
// back
function buildSubExpressionCall (
  path: Hbs.SubExpression,
  call: CallPlan,
  scopes: BlockParamScopes
): ValueFn {
  const inner = buildExpression(path, scopes)
  // a SubExpression carries no `.original` of its own, so name the path it
  // wraps, which is what the template actually spells
  const original = (path.path as Hbs.PathExpression | undefined)?.original
  return (frame) =>
    chain(inner(frame), (helperFn) => {
      const helper = asCallable(helperFn)
      if (!helper) {
        throw new Exception(
          'The path ' + original + ' did not return a function',
          path
        )
      }
      return runCall(call, helper, null, frame)
    })
}

// arguments are present, so this is definitely a call: a helper, else a
// callable found in the context, else helperMissing
function buildCall (plan: PathPlan, call: CallPlan, name: string | null): ValueFn {
  return (frame) => {
    if (name) {
      const helper = findHelper(frame, name)
      if (helper) {
        return runCall(call, helper, name, frame)
      }
    }
    const contextValue = resolvePlan(plan, frame)
    const callable = asCallable(contextValue)
    if (callable) {
      return runCall(call, callable, name, frame)
    }
    // calling a non-function throws an unreadable TypeError, so name it here
    if (contextValue != null) {
      throw new Exception(
        '"' + (name || plan.original) + '" is not a function',
        plan.node
      )
    }
    return runCall(
      call,
      missingHelper(frame, 'helperMissing'),
      name || plan.original,
      frame
    )
  }
}

// no arguments, so the name is ambiguous between a helper, a lambda in the
// context and a plain value. Helpers take precedence. `call` has no params or
// hash, only the location.
function buildAmbiguous (plan: PathPlan, call: CallPlan, name: string): ValueFn {
  return (frame) => {
    const helper = findHelper(frame, name)
    if (helper) {
      return runCall(call, helper, name, frame)
    }
    const value = resolvePlan(plan, frame)
    const lambda = asCallable(value)
    if (lambda) {
      // only an ambiguous simple id ({{foo}}) receives the options object
      return invoked(lambda.call(frame.context, helperOptions(name, {}, frame, undefined, undefined, call.loc)))
    }
    if (value == null) {
      return runCall(call, missingHelper(frame, 'helperMissing'), name, frame)
    }
    return value
  }
}

// mirrors the mustache half of upstream's classifySexpr. Only the registry is
// unknown at build time, so each shape gets its own closure
export function buildExpression (node: ExpressionHolder, scopes: BlockParamScopes): ValueFn {
  const rawPath = normalizePath(node.path)
  const call = planCall(node.params || [], node.hash, scopes, node.loc)

  if (rawPath.type === 'SubExpression') {
    return buildSubExpressionCall(rawPath as Hbs.SubExpression, call, scopes)
  }

  const plan = planPath(rawPath as Hbs.PathExpression, scopes)
  const isBlockParam = plan.simple && plan.blockParam !== null
  const name = plan.simple ? plan.parts[0] : null

  if (AST.helpers.helperExpression(node) && !isBlockParam) {
    return buildCall(plan, call, name)
  }
  if (name !== null && !isBlockParam) {
    return buildAmbiguous(plan, call, name)
  }
  return buildLookup(plan)
}
