/*
 * What a frame is, and the vocabulary that travels in one: helpers, partials,
 * programs and the runtime options. `derive` is here because every frame but
 * the root is made from another.
 */
import { noop as rawNoop } from '../lib/handlebars/runtime.js'
import { isFunction as rawIsFunction } from '../lib/handlebars/utils.js'
import type { Rendered } from './pending.ts'

export type NodeFn = (frame: Frame) => Rendered
export type ValueFn = (frame: Frame) => unknown

export type DataFrame = Record<string, unknown>

type LookupProperty = (parent: unknown, name: string) => unknown

export interface ProgramFnOptions {
  data?: DataFrame;
  blockParams?: unknown[];
}

// a helper that only `return options.fn(this)` passes the promise straight
// through, which is why `if`, `with` and `unless` need no async handling
export type ProgramFn = ((
  context?: unknown,
  fnOptions?: ProgramFnOptions
) => string | Promise<string>) & {
  blockParams?: number;
}

export const noopProgram = rawNoop as ProgramFn

export type Helper = (this: unknown, ...args: unknown[]) => unknown
export type HelpersMap = Record<string, Helper>

// the vendored guard infers as `=> boolean`, so it narrows nothing. Typed once
// as a predicate, so no call site has to cast what it just checked.
const isFunction = rawIsFunction as (value: unknown) => value is Helper

export function asCallable (value: unknown): Helper | undefined {
  return isFunction(value) ? value : undefined
}

// options arrive as `unknown` through the untyped registry
export function asHelperOptions (value: unknown): HelperOptions | undefined {
  return value != null && typeof value === 'object'
    ? (value as HelperOptions)
    : undefined
}

// what a function partial is called with. callPartial spreads the caller's
// runtime options in, so a partial sees them as it would upstream. An inline
// partial reads `data` and `partials` back off it.
export interface PartialCallOptions {
  helpers?: HelpersMap;
  partials?: PartialsMap;
  data?: DataFrame;
  [key: string]: unknown;
}

export type PartialFn = (context: unknown, options?: PartialCallOptions) => string | Promise<string>
export type Partial = PartialFn | string
export type PartialsMap = Readonly<Record<string, Partial>>

export interface RuntimeOptions {
  // an already-built frame, propagated from a parent render so @root and @index
  // survive the boundary
  data?: DataFrame;
  helpers?: HelpersMap;
  partials?: PartialsMap;
}

// where the call is written, the same shape upstream passes as options.loc.
// Lines count from 1, columns from 0. Not upstream: for a template or partial
// passed as a string, `source` is that text. Frozen, and shared by every call
// from the same place.
export interface HelperLocation {
  readonly source?: string;
  readonly start: { readonly line: number; readonly column: number };
  readonly end: { readonly line: number; readonly column: number };
}

export interface HelperOptions {
  name: string | null;
  hash: Record<string, unknown>;
  data: DataFrame;
  // undefined for an inline call, which is how helpers tell block from inline
  // usage
  fn?: ProgramFn;
  inverse?: ProgramFn;
  lookupProperty: LookupProperty;
  // undefined only for an AST built by hand without locations
  loc?: HelperLocation;
}

// block param names are gone from the frame: build resolves each reference to a
// (depth, slot) pair, so only the values travel at render time.
export interface Frame {
  context: unknown;
  data: DataFrame;
  depths: unknown[];
  helpers: HelpersMap;
  partials: PartialsMap;
  blockParamValues: unknown[][];
  lookupProperty: LookupProperty;
  options: RuntimeOptions;
}

// every frame but the root is its parent with a few fields replaced. A literal
// rather than a spread keeps them all on one hidden class.
export function derive (
  frame: Frame, context: unknown, data: DataFrame,
  depths: unknown[], partials: PartialsMap, blockParamValues: unknown[][]
): Frame {
  return {
    context, data, depths, helpers: frame.helpers, partials,
    blockParamValues, lookupProperty: frame.lookupProperty, options: frame.options,
  }
}

// shared stand-ins for "the caller passed none". Never written to.
export const emptyHelpers: HelpersMap = {}
export const emptyPartials: PartialsMap = {}
export const emptyValues: unknown[] = []
export const emptyScopes: BlockParamScopes = []

// innermost scope first, mirroring how frame.blockParamValues is stacked
export type BlockParamScopes = readonly (readonly string[])[]

// every unescaped output. A SafeString reaches its toString here. Only
// escapeExpression, on the `{{x}}` path, checks toHTML.
export function stringify (value: unknown): string {
  return value != null ? String(value) : ''
}
