/*
 * lib/ ships plain JS, so its helpers infer loose types that narrow nothing.
 * Cast once here, so no call site has to cast the value it just checked.
 */
import {
  escapeExpression as rawEscapeExpression,
  extend as rawExtend,
  isMap as rawIsMap,
} from '../lib/handlebars/utils.js'
import { invokePartial as rawInvokePartial } from '../lib/handlebars/runtime.js'
import type { PartialCallOptions, PartialFn } from './frame.ts'

export const escapeExpression = rawEscapeExpression as (value: unknown) => string
// variadic at runtime (it reads `arguments`), but declared with one parameter
export const extend = rawExtend as <T extends object>(
  obj: T,
  ...sources: unknown[]
) => T
export const isMap = rawIsMap as (value: unknown) => value is Map<unknown, unknown>
export const invokePartial = rawInvokePartial as (
  partial: PartialFn | undefined,
  context: unknown,
  options: PartialCallOptions
) => string | Promise<string> | undefined
