/*
 * The async protocol.
 *
 * Only a call out to user code can suspend, so only those results are wrapped
 * in `Pending` (see `invoked`). A value that needs another's result waits for
 * it through `chain`. Siblings do not wait for each other: the nodes of a body,
 * the params of a call, the values of a hash and the iterations of an each.
 * Once one suspends, `continueAll` starts the rest and settles them in order.
 * `settle` turns a Pending back into a real promise at a boundary. A render
 * that invokes nothing async never allocates a promise.
 */

// a render result that has not settled yet. `promise` is assigned rather than
// declared as a parameter property, which would emit code and break type
// stripping.
export class Pending {
  readonly promise: Promise<unknown>

  constructor (promise: Promise<unknown>) {
    this.promise = promise
  }
}

export type Rendered = string | Pending

// a thenable returned by a call is pending. One merely sitting in the template
// data is not, and stringifies to "[object Promise]". Adopted rather than
// chained onto, since a thenable's `then` may return nothing.
export function invoked (result: unknown): unknown {
  return result != null && typeof (result as { then?: unknown }).then === 'function'
    ? new Pending(Promise.resolve(result))
    : result
}

// lets a Pending be returned from inside a .then(), so the promise machinery
// flattens it instead of resolving to the wrapper
function unwrap (value: unknown): unknown {
  return value instanceof Pending ? value.promise : value
}

// deferral for a single value, in one place. Generic both ways, so a caller
// keeps its resolved type going in and gets `R | Pending` back with no cast.
export function chain<T, R> (
  value: T | Pending,
  then: (resolved: T) => R
): R | Pending {
  if (value instanceof Pending) {
    return new Pending(value.promise.then((resolved) => unwrap(then(resolved as T))))
  }
  return then(value)
}

// resolves to the values in document order. Promise.all handles every
// rejection, so none is reported as unhandled, but it rejects with whichever
// sibling failed first in time. Chaining them in order instead rejects with the
// first failure in the template, as soon as the siblings before it settle.
function settleInOrder (values: unknown[]): Promise<unknown[]> {
  const promises = values.map((value) => value instanceof Pending ? value.promise : value)
  return Promise.all(promises).catch(() => promises.reduce<Promise<unknown>>(
    (earlier, promise) => earlier.then(() => promise),
    Promise.resolve()
  ) as Promise<never>)
}

// the async half of a sibling loop. `values` holds what ran so far, ending with
// the step that suspended, and the steps after it start now instead of waiting
// for it. A step that throws ends the loop, since the steps after it would
// never have run, and rejects in its turn. `then` gets every value, settled and
// in order.
export function continueAll (
  values: unknown[],
  from: number,
  count: number,
  step: (i: number) => unknown,
  then: (settled: unknown[]) => unknown
): Pending {
  for (let i = from; i < count; i++) {
    try {
      values.push(step(i))
    } catch (err) {
      values.push(new Pending(Promise.reject(err)))
      break
    }
  }
  return new Pending(settleInOrder(values).then((settled) => unwrap(then(settled))))
}

// a loop over siblings. Runs synchronously until a step suspends, then hands
// the rest to continueAll and reports them to onValue in order once all
// settle.
export function runAll (
  count: number,
  step: (i: number) => unknown,
  onValue: (i: number, value: unknown) => void
): Pending | undefined {
  for (let i = 0; i < count; i++) {
    const value = step(i)
    if (value instanceof Pending) {
      return continueAll([value], i + 1, count, step, (settled) => {
        for (let k = 0; k < settled.length; k++) {
          onValue(i + k, settled[k])
        }
      })
    }
    onValue(i, value)
  }
  return undefined
}

export function settle (value: Rendered): string | Promise<string> {
  return value instanceof Pending
    ? (value.promise as Promise<string>)
    : value
}
