/*
 * The helper registry, and the one helper this interpreter replaces.
 *
 * The vendored `each` accumulates with `ret = ret + fn(...)`, which silently
 * breaks on an async block body, so `nativeEach` and the `Walker` below take
 * over. Overwriting the entry also redirects blockHelperMissing, which
 * forwards implicit array blocks to it.
 */
import { Exception } from '@handlebars/parser'
import { registerDefaultHelpers } from '../lib/handlebars/helpers.js'
import logger from '../lib/handlebars/logger.js'
import { createFrame, isArray } from '../lib/handlebars/utils.js'
import { isMap } from './vendor.ts'
import { Pending, chain, invoked, runAll } from './pending.ts'
import { asCallable, asHelperOptions, noopProgram, stringify } from './frame.ts'
import type { DataFrame, Frame, Helper, HelpersMap, ProgramFn, ProgramFnOptions } from './frame.ts'

// registered through the vendored entry point, so the set can't drift from
// lib/. The object passed in is upstream's registration interface.
const defaultHelpers: HelpersMap = {}
registerDefaultHelpers({
  helpers: defaultHelpers,
  registerHelper (name: string, fn: Helper) {
    defaultHelpers[name] = fn
  },
  log: logger.log,
})

defaultHelpers.each = nativeEach

// not upstream. Every `{{#each}}` iteration records which item it renders, so
// a helper can tell iterations apart by item rather than by position. Stored in
// the data frame, which createFrame copies into every frame below it, so
// `parent` is the enclosing loop's iteration however many other block helpers
// sit in between.
export interface LoopEntry {
  // the value of this iteration
  item: unknown;
  // @key: the index for arrays and iterables, the key for objects and Maps
  key: unknown;
  // @index
  index: number;
  // the values being walked, for arrays and iterables. null for objects and
  // Maps, whose key already identifies the item.
  items: unknown[] | null;
  parent: LoopEntry | undefined;
}

export const loopEntryKey = '_briskbarsLoop'

export function loopEntry (data: DataFrame | undefined): LoopEntry | undefined {
  return data ? (data[loopEntryKey] as LoopEntry | undefined) : undefined
}

// both names are own keys of defaultHelpers, so the builtin side needs no
// guard. A caller that overrode either with `undefined` reaches the TypeError.
export function missingHelper (
  frame: Frame,
  name: 'helperMissing' | 'blockHelperMissing'
): Helper {
  const helper = Object.prototype.hasOwnProperty.call(frame.helpers, name)
    ? frame.helpers[name]
    : defaultHelpers[name]
  if (!helper) {
    // reachable by passing `{ helperMissing: undefined }`. Upstream dies on
    // `undefined.call`, so keep the TypeError but name the cause.
    throw new TypeError('The "' + name + '" helper is not a function')
  }
  return helper
}

// caller's map first, then the builtins. A template may not name
// helperMissing/blockHelperMissing itself.
export function findHelper (frame: Frame, name: string): Helper | undefined {
  if (name === 'helperMissing' || name === 'blockHelperMissing') {
    throw new Exception('Missing helper: "' + name + '"')
  }
  // a passed `each` must not shadow ours, the one exception to caller-first
  if (name === 'each') {
    return defaultHelpers.each
  }
  // hasOwnProperty on both sides, or `{{constructor}}` reaches Object.prototype
  // and calls what it finds there. An own key shadows the builtin even when it
  // holds `undefined`.
  if (Object.prototype.hasOwnProperty.call(frame.helpers, name)) {
    return frame.helpers[name]
  }
  return Object.prototype.hasOwnProperty.call(defaultHelpers, name)
    ? defaultHelpers[name]
    : undefined
}

function nativeEach (this: unknown, ...args: unknown[]): unknown {
  const context = args[0]
  const options = asHelperOptions(args[1])
  if (!options) {
    throw new Exception('Must pass iterator to #each')
  }
  const fn = options.fn || noopProgram
  const inverse = options.inverse || noopProgram
  const iterable = asCallable(context)
  return chain(
    iterable ? invoked(iterable.call(this)) : context,
    (resolved) => eachOver(resolved, this, options.data, fn, inverse)
  )
}

// how to walk whatever `{{#each}}` was handed. `count` is slots, not values, so
// a sparse array counts its holes and the inverse stays unrun
interface Walker {
  count: number;
  fieldAt: (i: number) => unknown;
  valueAt: (i: number) => unknown;
  // the array being walked, since only an array can have holes. Null otherwise.
  maybeSparse: unknown[] | null;
}

// null for a non-object, so no walker exists whose accessors go unused
function walkerFor (context: unknown): Walker | null {
  if (!context || typeof context !== 'object') {
    return null
  }

  if (isMap(context)) {
    const entries = [...context]
    return {
      count: entries.length,
      fieldAt: (i) => entries[i][0],
      valueAt: (i) => entries[i][1],
      maybeSparse: null,
    }
  }

  if (isArray(context) || (context as Record<symbol, unknown>)[Symbol.iterator]) {
    const arr = (isArray(context)
      ? context
      : Array.from(context as Iterable<unknown>)) as unknown[]
    return {
      count: arr.length,
      fieldAt: (i) => i,
      valueAt: (i) => arr[i],
      maybeSparse: arr,
    }
  }

  const obj = context as Record<string, unknown>
  const keys = Object.keys(obj)
  return {
    count: keys.length,
    fieldAt: (i) => keys[i],
    valueAt: (i) => obj[keys[i]],
    maybeSparse: null,
  }
}

function eachOver (
  context: unknown,
  self: unknown,
  parentData: DataFrame,
  fn: ProgramFn,
  inverse: ProgramFn
): unknown {
  const walker = walkerFor(context)
  if (!walker || walker.count === 0) {
    return chain(invoked(inverse(self)), stringify)
  }
  const count = walker.count

  // a body without `as |x y|` ignores fnOptions.blockParams, so skip the array
  const wantsBlockParams = !!fn.blockParams
  // one data frame and options object reused across iterations. An iteration
  // that suspends keeps reading its @index after the next one starts, so the
  // next one gets a fresh pair.
  let data: DataFrame
  let iterOptions: ProgramFnOptions
  const freshFrame = (): void => {
    data = createFrame(parentData)
    iterOptions = wantsBlockParams ? { data, blockParams: undefined } : { data }
  }
  freshFrame()

  let ret = ''
  const parentEntry = loopEntry(parentData)

  const step = (i: number): unknown => {
    // a hole in a sparse array is a slot with no iteration
    if (walker.maybeSparse && !(i in walker.maybeSparse)) {
      return ''
    }
    const field = walker.fieldAt(i)
    data.key = field
    data.index = i
    data.first = i === 0
    data.last = i === count - 1
    const value = walker.valueAt(i)
    const entry: LoopEntry = {
      item: value,
      key: field,
      index: i,
      items: walker.maybeSparse,
      parent: parentEntry,
    }
    data[loopEntryKey] = entry
    if (wantsBlockParams) {
      // the value itself, since upstream's `context[field]` misses on a Map or
      // Set
      iterOptions.blockParams = [value, field]
    }
    const piece = invoked(fn(value, iterOptions))
    if (piece instanceof Pending) {
      freshFrame()
    }
    return piece
  }

  const pending = runAll(count, step, (_i, piece) => { ret += (piece as string) || '' })
  return pending ? new Pending(pending.promise.then(() => ret)) : ret
}
